```python
"""A small worker thread that consumes items from a queue.Queue."""

import logging
import queue
import threading

log = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Runs `callback(item)` on a background thread for each queued item."""

    def __init__(self, callback, maxsize=0, name="queue-worker"):
        self.callback = callback
        self.queue = queue.Queue(maxsize=maxsize)
        self._thread = threading.Thread(target=self._run, name=name, daemon=True)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()
        return self

    def submit(self, item, block=True, timeout=None):
        self.queue.put(item, block=block, timeout=timeout)

    def _run(self):
        while True:
            item = self.queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self.callback(item)
            except Exception:
                log.exception("callback failed for %r", item)
            finally:
                self.queue.task_done()

    def join(self):
        """Block until everything submitted so far has been processed."""
        self.queue.join()

    def stop(self, timeout=None):
        """Finish queued work, then shut the thread down."""
        if not self._started:
            return
        self.queue.put(_SHUTDOWN)
        self._thread.join(timeout)

    def __enter__(self):
        return self.start()

    def __exit__(self, *exc):
        self.stop()
        return False


if __name__ == "__main__":
    with QueueWorker(lambda n: print(f"got {n} -> {n * n}")) as worker:
        for i in range(5):
            worker.submit(i)
        worker.join()
```

Notes on the design choices worth knowing:

- **`_SHUTDOWN` sentinel instead of a flag.** A `while not self._stopped` loop paired with a blocking `get()` can park forever on an empty queue; the sentinel wakes the thread immediately and guarantees every item queued before it is processed first.
- **Exceptions are logged, not raised.** An escaping exception would kill the thread and silently strand the queue. `task_done()` sits in `finally` so `join()` can't deadlock after a failed callback.
- **`stop()` drains.** If you want to discard pending work instead, add a `drain=False` path that empties the queue before pushing the sentinel.
- Single consumer thread. For N workers, spawn N threads over the same queue and push N sentinels.
